alter table public.compras add column if not exists tipo_periodo_compra text;
alter table public.compras add column if not exists retencion_iva numeric;
alter table public.compras add column if not exists aplica_ret_iva boolean;
alter table public.compras add column if not exists exencion boolean;
alter table public.compras add column if not exists transaccion_retencion integer;
alter table public.compras add column if not exists empresa_anterior integer;
alter table public.compras add column if not exists completada boolean;
alter table public.compras add column if not exists total_sin_descuentos numeric;
alter table public.compras add column if not exists descuentos_anterior numeric;
alter table public.compras add column if not exists fecha_contabilizacion timestamp;
alter table public.compras add column if not exists fecha_conta_anula timestamp;
alter table public.compras add column if not exists aplica_orden boolean;
alter table public.compras add column if not exists compra_ref integer;
alter table public.compras add column if not exists valor_total_q numeric;
alter table public.compras add column if not exists valor_total_mi numeric;
alter table public.compras add column if not exists valor_cambio_anterior numeric;
alter table public.compras add column if not exists forma_compra text;
alter table public.compras add column if not exists muestra boolean;
alter table public.compras add column if not exists origen_anterior text;
alter table public.compras add column if not exists compra_anterior integer;
alter table public.compras add column if not exists compra_varia_anterior integer;
create index if not exists compras_varia_anterior_idx on public.compras (localidad_id, compra_varia_anterior) where compra_varia_anterior is not null;
create unique index if not exists compras_origen_anterior_uk on public.compras (localidad_id, origen_anterior, compra_anterior) where origen_anterior is not null;

do $migra$
declare
  v_org bigint;
  v_nuevas integer := 0;
  v_act integer := 0;
  v_conflictos text;
  v_sin_prov text;
