  select string_agg(format('3-%s %s %s (número %s)', lpad(m.loc::text, 2, '0'), m.origen, m.compra, m.numero), '; ') into v_conflictos
  from m_compras m join public.localidades l on l.organizacion_id = v_org and l.correlativo = m.loc
  join public.compras c on c.localidad_id = l.id and c.numero = m.numero
  where c.origen_anterior is distinct from m.origen or c.compra_anterior is distinct from m.compra;
  delete from m_compras m using public.localidades l, public.compras c
  where l.organizacion_id = v_org and l.correlativo = m.loc and c.localidad_id = l.id and c.numero = m.numero
    and (c.origen_anterior is distinct from m.origen or c.compra_anterior is distinct from m.compra);
  select string_agg(distinct format('3-%s %s', lpad(m.loc::text, 2, '0'), m.proveedor), '; ') into v_sin_prov
  from m_compras m join public.localidades l on l.organizacion_id = v_org and l.correlativo = m.loc
  where m.proveedor is not null and not exists (select 1 from public.proveedores p where p.localidad_id = l.id and p.codigo = m.proveedor);

  -- La numeración y el estado vienen del archivo: el trigger que los asigna se suspende durante la carga.
  alter table public.compras disable trigger compras_preparar;
  with x as (
    insert into public.compras (organizacion_id, localidad_id, numero, tipo_documento, tipo_documento_id, serie, documento, fecha_documento, fecha_ingreso,
           fecha_vencimiento, tipo_tercero, proveedor_id, proveedor_codigo, proveedor_nombre, nit, beneficiario, transaccion_id, descripcion, moneda_id,
           tipo_cambio, valor_total, bonificaciones, notas_credito, descuentos_nd, forma_pago, estado, anulado_por, anulado_en, motivo_anulacion, usuario,
           mes_presentacion, anio_presentacion, pago_inmediato, dias_credito, factura_original, regimen_isr_id, clasificacion_id, bodega_id,
           galones_super, galones_regular, galones_diesel, exento, iva_especial, isr_especial, aplica_inguat, retencion, retencion_valor, retencion_formulario,
           orden_compra, origen_anterior, compra_anterior, compra_varia_anterior, modulo_factura, numero_cheque, usuario_modifica_anterior, fecha_modifica_anterior, tipo_compra_anterior, poliza_anio, poliza_mes, poliza_numero, pct_iva, pct_retencion, propina, fecha_transferencia, clasificacion_pago, total_nc2, total_nc3, usuario_autoriza, tipo_periodo_compra, retencion_iva, aplica_ret_iva, exencion, transaccion_retencion, empresa_anterior, completada, total_sin_descuentos, descuentos_anterior, fecha_contabilizacion, fecha_conta_anula, aplica_orden, compra_ref, valor_total_q, valor_total_mi, valor_cambio_anterior, forma_compra, muestra)
    select v_org, l.id, m.numero, case when t.es_recibo then 'RECIBO' else 'FACTURA' end, t.id, m.serie, coalesce(m.documento, 'S/N'), m.fecha_documento,
           coalesce(m.fecha_ingreso, m.fecha_documento), m.fecha_vencimiento,
           case when m.origen = 'MEDICAMENTOS' then 'PROVEEDOR PRODUCTOS' else 'PROVEEDOR SERVICIOS' end,
           p.id, m.proveedor::text, coalesce(p.nombre_comercial, case when m.proveedor is null then 'SIN PROVEEDOR' else 'PROVEEDOR ' || m.proveedor end), p.nit, p.beneficiario,
           (select x.id from public.transacciones_contables x where x.localidad_id = l.id and x.numero = m.transaccion),
           m.descripcion, coalesce((select x.id from public.monedas x where x.codigo = m.moneda), (select x.id from public.monedas x where x.iso = 'GTQ')),
           m.tipo_cambio, m.valor_total, m.bonificaciones, m.notas_credito, m.descuentos_nd, 'CHEQUE', m.estado,
           case when m.estado = 'ANULADA' then 'SISTEMA ANTERIOR' end, case when m.estado = 'ANULADA' then coalesce(m.anulado_en, m.fecha_ingreso) end,
           case when m.estado = 'ANULADA' then 'ANULADA EN EL SISTEMA ANTERIOR' end, m.usuario,
           m.mes_pres, m.anio_pres, m.pago_inmediato,
           case when m.pago_inmediato or m.fecha_vencimiento is null then 0 else greatest(m.fecha_vencimiento - m.fecha_documento, 0) end,
           m.original, (select x.id from public.regimenes_isr x where x.codigo = m.regimen),
           (select x.id from public.clasificaciones_compra x where x.codigo = m.clasif),
           (select x.id from public.bodegas x where x.localidad_id = l.id and x.codigo = m.bodega),
           m.galones_super, m.galones_regular, m.galones_diesel, m.exento, m.iva_especial, m.isr_especial, m.aplica_inguat, coalesce(m.retencion, false),
           m.retencion_valor, m.retencion_formulario, m.orden_compra, m.origen, m.compra, m.compra_varia, m.modulo_factura, m.numero_cheque, m.usuario_modifica_anterior, m.fecha_modifica_anterior, m.tipo_compra_anterior, m.poliza_anio, m.poliza_mes, m.poliza_numero, m.pct_iva, m.pct_retencion, m.propina, m.fecha_transferencia, m.clasificacion_pago, m.total_nc2, m.total_nc3, m.usuario_autoriza, m.tipo_periodo_compra, m.retencion_iva, m.aplica_ret_iva, m.exencion, m.transaccion_retencion, m.empresa_anterior, m.completada, m.total_sin_descuentos, m.descuentos_anterior, m.fecha_contabilizacion, m.fecha_conta_anula, m.aplica_orden, m.compra_ref, m.valor_total_q, m.valor_total_mi, m.valor_cambio_anterior, m.forma_compra, m.muestra
    from m_compras m
    join public.localidades l on l.organizacion_id = v_org and l.correlativo = m.loc
    left join public.proveedores p on p.localidad_id = l.id and p.codigo = m.proveedor
    left join public.tipos_documento_compra t on t.codigo = m.tipo_doc
    on conflict (localidad_id, origen_anterior, compra_anterior) where origen_anterior is not null do update set
      numero = excluded.numero, tipo_documento = excluded.tipo_documento, tipo_documento_id = excluded.tipo_documento_id, serie = excluded.serie,
      documento = excluded.documento, fecha_documento = excluded.fecha_documento, fecha_ingreso = excluded.fecha_ingreso,
      fecha_vencimiento = excluded.fecha_vencimiento, tipo_tercero = excluded.tipo_tercero, proveedor_id = excluded.proveedor_id,
      proveedor_codigo = excluded.proveedor_codigo, proveedor_nombre = excluded.proveedor_nombre, nit = excluded.nit, beneficiario = excluded.beneficiario,
      transaccion_id = excluded.transaccion_id, descripcion = excluded.descripcion, moneda_id = excluded.moneda_id, tipo_cambio = excluded.tipo_cambio,
      valor_total = excluded.valor_total, bonificaciones = excluded.bonificaciones, notas_credito = excluded.notas_credito,
      descuentos_nd = excluded.descuentos_nd, estado = excluded.estado, anulado_por = excluded.anulado_por, anulado_en = excluded.anulado_en,
      motivo_anulacion = excluded.motivo_anulacion, usuario = excluded.usuario, mes_presentacion = excluded.mes_presentacion,
      anio_presentacion = excluded.anio_presentacion, pago_inmediato = excluded.pago_inmediato, dias_credito = excluded.dias_credito,
      factura_original = excluded.factura_original, regimen_isr_id = excluded.regimen_isr_id, clasificacion_id = excluded.clasificacion_id,
      bodega_id = excluded.bodega_id, galones_super = excluded.galones_super, galones_regular = excluded.galones_regular,
      galones_diesel = excluded.galones_diesel, exento = excluded.exento, iva_especial = excluded.iva_especial, isr_especial = excluded.isr_especial,
      aplica_inguat = excluded.aplica_inguat, retencion = excluded.retencion, retencion_valor = excluded.retencion_valor,
      retencion_formulario = excluded.retencion_formulario, orden_compra = excluded.orden_compra, compra_varia_anterior = excluded.compra_varia_anterior,
      modulo_factura = excluded.modulo_factura, numero_cheque = excluded.numero_cheque,
      usuario_modifica_anterior = excluded.usuario_modifica_anterior,
      fecha_modifica_anterior = excluded.fecha_modifica_anterior,
      tipo_compra_anterior = excluded.tipo_compra_anterior, poliza_anio = excluded.poliza_anio,
      poliza_mes = excluded.poliza_mes, poliza_numero = excluded.poliza_numero, pct_iva = excluded.pct_iva,
      pct_retencion = excluded.pct_retencion, propina = excluded.propina,
      fecha_transferencia = excluded.fecha_transferencia, clasificacion_pago = excluded.clasificacion_pago,
      total_nc2 = excluded.total_nc2, total_nc3 = excluded.total_nc3, usuario_autoriza = excluded.usuario_autoriza,
      tipo_periodo_compra = excluded.tipo_periodo_compra, retencion_iva = excluded.retencion_iva,
      aplica_ret_iva = excluded.aplica_ret_iva, exencion = excluded.exencion,
      transaccion_retencion = excluded.transaccion_retencion, empresa_anterior = excluded.empresa_anterior,
      completada = excluded.completada, total_sin_descuentos = excluded.total_sin_descuentos,
      descuentos_anterior = excluded.descuentos_anterior, fecha_contabilizacion = excluded.fecha_contabilizacion,
      fecha_conta_anula = excluded.fecha_conta_anula, aplica_orden = excluded.aplica_orden,
      compra_ref = excluded.compra_ref, valor_total_q = excluded.valor_total_q,
      valor_total_mi = excluded.valor_total_mi, valor_cambio_anterior = excluded.valor_cambio_anterior,
      forma_compra = excluded.forma_compra, muestra = excluded.muestra
    returning (xmax = 0) as nueva)
  select count(*) filter (where nueva), count(*) filter (where not nueva) into v_nuevas, v_act from x;
  alter table public.compras enable trigger compras_preparar;

  raise notice '%', format('Compras de la organización 3 (encabezados): %s nuevas, %s actualizadas.%s%s',
    v_nuevas, v_act,
    case when v_conflictos is not null then ' Omitidas porque su número ya lo usa otra compra: ' || v_conflictos || '.' else '' end,
    case when v_sin_prov is not null then ' Proveedores que no existen (queda su código): ' || v_sin_prov || '.' else '' end);
  drop table m_compras;
end;
$migra$;

notify pgrst, 'reload schema';
